def solve(tokens):
    stack = []
    ops = {'+', '-', '*', '/'}
    for t in tokens:
        if t in ops:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division truncates toward zero
                # In Python, -a//b rounds down. For truncation toward zero: int(a/b).
                v = a / b
                if v >= 0:
                    stack.append(int(v))
                else:
                    stack.append(-int(-v))
        else:
            stack.append(int(t))
    return stack[0] if isinstance(stack[0], int) else int(stack[0])

