def solve(nums):
    if not nums:
        return 0
    # O(n log n) patience sorting
    tails = []
    for x in nums:
        # binary search for leftmost tail >= x
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

