def solve(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                count += 1
                # flood fill with 0
                stack = [(r, c)]
                while stack:
                    x, y = stack.pop()
                    if x < 0 or x >= rows or y < 0 or y >= cols:
                        continue
                    if grid[x][y] != 1:
                        continue
                    grid[x][y] = 0
                    stack.append((x+1, y))
                    stack.append((x-1, y))
                    stack.append((x, y+1))
